package hk.jimmy.wearmemory;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.io.*;import java.text.*;import java.util.*;
/** Visual craft adapted from unslop by Damir Sokolovsky (@heydamir), CC BY 4.0. */
public class Ui {
static final int BG=Color.rgb(20,20,21),SURFACE=Color.rgb(29,29,31),FG=Color.rgb(237,237,233),SECOND=Color.rgb(173,173,170),MUTED=Color.rgb(145,145,143),ACC=Color.rgb(164,190,174),LINE=Color.rgb(47,47,49);
static final boolean WATCH=false;
static int dp(Context c,float n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
static GradientDrawable shape(int color,int radius,Context c){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(c,radius));return d;}
static TextView label(Context c,String value,int size,int color){TextView t=new TextView(c);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setFontFeatureSettings("tnum");t.setIncludeFontPadding(false);t.setLineSpacing(dp(c,4),1f);return t;}
static LinearLayout page(Activity a,String title){a.getWindow().setStatusBarColor(BG);a.getWindow().setNavigationBarColor(BG);ScrollView s=new ScrollView(a);s.setFillViewport(true);s.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets bars=insets.getInsets(android.view.WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});s.setClipToPadding(false);s.setBackgroundColor(BG);LinearLayout l=new LinearLayout(a);l.setOrientation(1);l.setPadding(dp(a,WATCH?28:24),dp(a,WATCH?36:24),dp(a,WATCH?28:24),dp(a,WATCH?48:40));s.addView(l);a.setContentView(s);
 TextView brand=label(a,WATCH?"Wear Memory":"Wear Memory  /  私人聲音日誌",12,MUTED);l.addView(brand);LinearLayout.LayoutParams bp=(LinearLayout.LayoutParams)brand.getLayoutParams();bp.bottomMargin=dp(a,16);brand.setLayoutParams(bp);
 TextView heading=label(a,title,WATCH?24:30,FG);heading.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));l.addView(heading);LinearLayout.LayoutParams hp=(LinearLayout.LayoutParams)heading.getLayoutParams();hp.bottomMargin=dp(a,16);heading.setLayoutParams(hp);return l;}
static TextView text(Context c,LinearLayout l,String value,int size){TextView t=label(c,value,size>=24?size:(size>=16?16:13),size>=16?FG:MUTED);if(size>=16){t.setTextIsSelectable(true);}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(c,16);t.setLayoutParams(p);l.addView(t);return t;}
static void section(Context c,LinearLayout l,String value){TextView t=label(c,value,13,SECOND);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(c,24);p.bottomMargin=dp(c,12);l.addView(t,p);}
static void note(Context c,LinearLayout l,String caption,String value){LinearLayout box=new LinearLayout(c);box.setOrientation(1);box.setPadding(dp(c,20),dp(c,20),dp(c,20),dp(c,20));box.setBackground(shape(SURFACE,16,c));TextView cap=label(c,caption,12,ACC);box.addView(cap);TextView body=label(c,value,16,FG);LinearLayout.LayoutParams b=new LinearLayout.LayoutParams(-1,-2);b.topMargin=dp(c,12);box.addView(body,b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(c,16);l.addView(box,p);}
static void button(Context c,LinearLayout l,String title,Runnable action){boolean primary=title.equals("今日回顧")||title.equals("開始錄音")||title.equals("播放／停止");boolean back=title.equals("返回");boolean danger=title.startsWith("刪除");LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.setOrientation(0);row.setPadding(dp(c,WATCH?12:16),dp(c,12),dp(c,WATCH?12:16),dp(c,12));row.setMinimumHeight(dp(c,WATCH?48:56));row.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x22ffffff),shape(primary?ACC:back?BG:SURFACE,10,c),null));row.setFocusable(true);row.setClickable(true);row.setContentDescription(title);TextView label=label(c,title,15,primary?BG:danger?Color.rgb(225,157,151):FG);label.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));row.addView(label,new LinearLayout.LayoutParams(0,-2,1));if(!WATCH&&!primary&&!back&&!danger){TextView arrow=label(c,"›",22,MUTED);row.addView(arrow);}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(c,8);l.addView(row,p);row.setOnClickListener(v->action.run());}
static void notify(Context c,int id,String title,String body){NotificationManager n=c.getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("memory","Wear Memory",NotificationManager.IMPORTANCE_LOW));PendingIntent pi=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);n.notify(id,new Notification.Builder(c,"memory").setSmallIcon(android.R.drawable.ic_menu_recent_history).setContentTitle(title).setContentText(body).setContentIntent(pi).setAutoCancel(true).build());}
static File dir(Context c,String n){File f=new File(c.getFilesDir(),n);f.mkdirs();return f;}
static String read(File f){try{return new String(java.nio.file.Files.readAllBytes(f.toPath()),java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){return "";}}
static void write(File f,String s)throws Exception {File tmp=new File(f.getPath()+".tmp");try(FileOutputStream o=new FileOutputStream(tmp)){o.write(s.getBytes(java.nio.charset.StandardCharsets.UTF_8));o.getFD().sync();}if(!tmp.renameTo(f))throw new IOException("Cannot commit file");}
static String day(long ms){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date(ms));}
}